# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Generated secrets"
say "Three values nobody hands you — generated locally, never leaving this box"
say "except into the .env file and your GitHub secrets."
say ""
note "ALCHEMY_PASSWORD     encrypts secrets inside Alchemy's state store."
note "ALCHEMY_STATE_TOKEN  bearer auth for CloudflareStateStore's own"
note "                     Durable Object worker (ADR 0008)."
note "BETTER_AUTH_SECRET   signs betterauth session cookies."
say ""
warn "Losing ALCHEMY_PASSWORD makes existing Alchemy state undecryptable."
warn "Rotating ALCHEMY_STATE_TOKEN locks out the existing state worker."
warn "Rotating BETTER_AUTH_SECRET signs every user out."
note "Put all three in your password manager before you finish this wizard."
say ""

_gen() { openssl rand -base64 32 2>/dev/null || head -c 32 /dev/urandom | base64; }

ALCHEMY_PASSWORD=$(_existing ALCHEMY_PASSWORD || true)
if [[ -n "$ALCHEMY_PASSWORD" ]]; then
  note "ALCHEMY_PASSWORD already in $ENV_FILE — keeping it."
else
  ALCHEMY_PASSWORD=$(_gen)
  say "Generated a new ALCHEMY_PASSWORD."
fi
write_env ALCHEMY_PASSWORD "$ALCHEMY_PASSWORD"

ALCHEMY_STATE_TOKEN=$(_existing ALCHEMY_STATE_TOKEN || true)
if [[ -n "$ALCHEMY_STATE_TOKEN" ]]; then
  note "ALCHEMY_STATE_TOKEN already in $ENV_FILE — keeping it."
else
  ALCHEMY_STATE_TOKEN=$(_gen)
  say "Generated a new ALCHEMY_STATE_TOKEN."
fi
write_env ALCHEMY_STATE_TOKEN "$ALCHEMY_STATE_TOKEN"

